}

theory/dimension.sl.content:
shape theory.dimension : theory.emergence, theory.coherence.law1, theory.coherence.law2, theory.coherence.law3 {
  type: definition
  layer: 0
  """
// Section 8 (Dimensionality).
// A single shape has internal structure through self-contact, but
// no spatial structure. Dimensionality arises from the structure
