shape world.scene.node : world.scene {
  type: exec
  layer: 5
  """
// A scene node. The building block of worlds.
//
// Dimensions:
//   position: "x,y,z"
//   rotation: "rx,ry,rz" (Euler angles, degrees)
//   scale: "sx,sy,sz"
//   mesh: shape ID of the mesh
//   material: shape ID of the material
//   visible: "true" or "false"
//
// Children are shapes that depend on this node.
// Moving the parent moves all children (wave propagation).
//
// The node IS its transform. The transform IS the relationship
// between the node and its parent. The scene graph IS the
// composition of all these relationships.
"""
}

shape world.scene.mesh : world.scene {
  type: data
  layer: 5
  """
// A mesh: vertices + triangles.
//
// Vertices: shapes under mesh_id.v.N with content "x,y,z"
// Triangles: shapes under mesh_id.t.N with content "v0,v1,v2"
//   where v0,v1,v2 are vertex indices.
//
// Primitive meshes:
//   cube: 8 vertices, 12 triangles
//   plane: 4 vertices, 2 triangles
//   sphere: N*M vertices, 2*N*M triangles (UV sphere)
"""
}

shape world.scene.mesh.cube : world.scene.mesh {
  type: exec
  layer: 5
  """
// Create a unit cube mesh as shapes.
// 8 vertices, 12 triangles (2 per face).

let id = mesh_id

// Vertices: corners of [-1,1] cube.
add_shape(id + ".v.0", "vertex", "-1,-1,-1", 5)
add_shape(id + ".v.1", "vertex", "1,-1,-1", 5)
add_shape(id + ".v.2", "vertex", "1,1,-1", 5)
add_shape(id + ".v.3", "vertex", "-1,1,-1", 5)
add_shape(id + ".v.4", "vertex", "-1,-1,1", 5)
add_shape(id + ".v.5", "vertex", "1,-1,1", 5)
add_shape(id + ".v.6", "vertex", "1,1,1", 5)
add_shape(id + ".v.7", "vertex", "-1,1,1", 5)

// Triangles: 2 per face, 6 faces = 12 triangles.
// Front face (z=-1)
add_shape(id + ".t.0", "triangle", "0,1,2", 5)
add_shape(id + ".t.1", "triangle", "0,2,3", 5)
// Back face (z=1)
add_shape(id + ".t.2", "triangle", "5,4,7", 5)
add_shape(id + ".t.3", "triangle", "5,7,6", 5)
// Left face (x=-1)
add_shape(id + ".t.4", "triangle", "4,0,3", 5)
add_shape(id + ".t.5", "triangle", "4,3,7", 5)
// Right face (x=1)
add_shape(id + ".t.6", "triangle", "1,5,6", 5)
add_shape(id + ".t.7", "triangle", "1,6,2", 5)
// Top face (y=1)
add_shape(id + ".t.8", "triangle", "3,2,6", 5)
add_shape(id + ".t.9", "triangle", "3,6,7", 5)
// Bottom face (y=-1)
add_shape(id + ".t.10", "triangle", "4,5,1", 5)
add_shape(id + ".t.11", "triangle", "4,1,0", 5)

print("Created cube: 8 vertices, 12 triangles")
"""
}

shape world.scene.mesh.plane : world.scene.mesh {
  type: exec
  layer: 5
  """
// Create a unit plane mesh (XZ plane, Y=0).
let id = mesh_id
add_shape(id + ".v.0", "vertex", "-1,0,-1", 5)
add_shape(id + ".v.1", "vertex", "1,0,-1", 5)
add_shape(id + ".v.2", "vertex", "1,0,1", 5)
add_shape(id + ".v.3", "vertex", "-1,0,1", 5)
add_shape(id + ".t.0", "triangle", "0,1,2", 5)
add_shape(id + ".t.1", "triangle", "0,2,3", 5)
print("Created plane: 4 vertices, 2 triangles")
"""
}

world/terrain.sl.content:
// Terrain: procedural landscape as shapes.
//
// A heightmap IS a 2D grid of height values. Each cell IS a shape.
// Procedural generation IS structural: noise IS a fractal shape.
// Each octave of noise IS an emergence level.
// The terrain IS the sum of all octaves. That's fractal coherence.

shape world.terrain : world {
  type: system
  layer: 5
  deps: [world.scene, hardware.gpu.framebuffer]
  "Procedural terrain. Heightmaps, noise, erosion. Fractal shapes."
}

shape world.terrain.heightmap : world.terrain {
  type: exec
  layer: 5
  """
// Generate a heightmap using simple hash-based noise.
// width, height: grid dimensions.
// seed: random seed.
// octaves: number of noise layers (more = more detail).
//
// Each octave doubles the frequency and halves the amplitude.
// This IS the polynomial fractal: each level adds structure
// at a finer scale.

let w = to_int(default(width, "64"))
let h = to_int(default(height, "64"))
let s = to_int(default(seed, "42"))
let oct = to_int(default(octaves, "4"))

for y in range(h) {
  for x in range(w) {
    let height_val = 0
    let amp = 128
    let freq = 1

    for o in range(oct) {
      // Simple integer hash noise.
      let nx = x * freq + s
      let ny = y * freq + s * 7
      let hash = mod(nx * 73856093 + ny * 19349663, 256)
      // Smooth: average with neighbors.
      let hash2 = mod((nx + 1) * 73856093 + ny * 19349663, 256)
      let hash3 = mod(nx * 73856093 + (ny + 1) * 19349663, 256)
      let smooth = (hash + hash2 + hash3) / 3
      set height_val = height_val + smooth * amp / 256
      set amp = amp / 2
      set freq = freq * 2
    }

    let hid = "world.terrain.h." + to_string(x) + "." + to_string(y)
    add_shape(hid, "height", to_string(height_val), 5)
  }
}
print("Generated " + to_string(w) + "x" + to_string(h) + " heightmap, " + to_string(oct) + " octaves")
"""
}

world/physics.sl.content:
// Physics: simulation as wave propagation.
//
// Gravity IS a force shape that propagates to all bodies.
// Collision IS a contact shape that resolves by the laws of coherence.
// A rigid body IS a shape with mass, velocity, and position.
// Physics stepping IS one tick of wave propagation through all bodies.
//
// The physics engine doesn't simulate. It propagates. Same mechanism
// as the shape engine's wave propagation through dependents.
// A force IS a wave. A collision IS a contact resolution.
// Conservation of momentum IS Law 2 (conservation).
// Objects can't overlap IS Law 3 (consistency).

shape world.physics : world {
  type: system
  layer: 5
  "Physics. Forces, collisions, constraints. All wave propagation."
}

shape world.physics.body : world.physics {
  type: data
  layer: 5
  """
// A rigid body.
// Dimensions:
//   position: "x,y,z"
//   velocity: "vx,vy,vz"
//   mass: number (0 = static/infinite mass)
//   restitution: bounciness (0-1)
//   shape: "sphere,radius" or "box,hx,hy,hz"
"""
}

shape world.physics.step : world.physics {
  type: exec
  layer: 5
  """
// Advance physics by one timestep.
// dt: time step in milliseconds.
//
// For each body:
//   1. Apply gravity: velocity.y -= 9.81 * dt
//   2. Integrate: position += velocity * dt
//   3. Detect collisions (ground plane at y=0 for now)
//   4. Resolve: reflect velocity, apply restitution
//
// This IS one tick of wave propagation.
// Gravity IS a wave from the ground to all bodies.
// Collision IS a contact wave between two bodies.

let bodies = children("world.physics.body")
let gravity = 10  // simplified, integer

for name in bodies {
  let bid = "world.physics.body." + name
  let pos = dim(bid, "position")
  let vel = dim(bid, "velocity")
  let mass = to_int(dim(bid, "mass"))
  let bounce = to_int(dim(bid, "restitution"))

  if mass > 0 {
    let pp = split(pos, ",")
    let vp = split(vel, ",")
    let px = to_int(index(pp, 0))
    let py = to_int(index(pp, 1))
    let pz = to_int(index(pp, 2))
    let vx = to_int(index(vp, 0))
    let vy = to_int(index(vp, 1))
    let vz = to_int(index(vp, 2))

    // Gravity.
    set vy = vy - gravity * dt / 1000

    // Integrate.
    set px = px + vx * dt / 1000
    set py = py + vy * dt / 1000
    set pz = pz + vz * dt / 1000

    // Ground collision (y=0 plane).
    if py < 0 {
      set py = 0
      set vy = 0 - vy * bounce / 100
    }

    set_dim(bid, "position", to_string(px) + "," + to_string(py) + "," + to_string(pz))
    set_dim(bid, "velocity", to_string(vx) + "," + to_string(vy) + "," + to_string(vz))
  }
}
"""
}

world/entity.sl.content:
// Entity: things in the world.
//
// An entity IS a shape with components. Components are child shapes.
// Entity-component-system IS the shape graph:
//   Entity = parent shape
//   Component = child shapes (position, mesh, physics, script, etc.)
//   System = wave propagation through all entities with a given component
//
// The ECS pattern IS the shape pattern. They're the same thing.
// The shape engine IS an ECS engine. We didn't add ECS. It was always there.

shape world.entity : world {
  type: system
  layer: 5
  "Entities. Characters, objects, particles. Components are shapes."
}

shape world.entity.create : world.entity {
  type: exec
  layer: 5
  """
// Create an entity with components.
// name: entity name (becomes world.entity.NAME)
// components: comma-separated list of component types.
//
// Each component type creates a child shape:
//   transform -> position, rotation, scale
//   mesh -> geometry reference
//   physics -> rigid body
//   script -> behavior (shape-lang code)
//   light -> point/directional/spot
//   camera -> projection + view
//   audio -> sound source
//   particle -> emitter settings

let eid = "world.entity." + name
add_shape(eid, "entity", "", 5)

let comps = split(components, ",")
for comp in comps {
  let cname = trim(comp)
  if cname == "transform" {
    add_shape(eid + ".transform", "component", "", 5)
    set_dim(eid + ".transform", "position", "0,0,0")
    set_dim(eid + ".transform", "rotation", "0,0,0")
    set_dim(eid + ".transform", "scale", "1,1,1")
  } else if cname == "mesh" {
    add_shape(eid + ".mesh", "component", "", 5)
    set_dim(eid + ".mesh", "ref", "")
  } else if cname == "physics" {
    add_shape(eid + ".physics", "component", "", 5)
    set_dim(eid + ".physics", "velocity", "0,0,0")
    set_dim(eid + ".physics", "mass", "1")
    set_dim(eid + ".physics", "restitution", "50")
  } else if cname == "light" {
    add_shape(eid + ".light", "component", "", 5)
    set_dim(eid + ".light", "type", "point")
    set_dim(eid + ".light", "color", "255,255,255")
    set_dim(eid + ".light", "intensity", "100")
  } else if cname == "camera" {
    add_shape(eid + ".camera", "component", "", 5)
    set_dim(eid + ".camera", "fov", "60")
    set_dim(eid + ".camera", "near", "1")
    set_dim(eid + ".camera", "far", "1000")
  } else if cname == "script" {
    add_shape(eid + ".script", "component", "", 5)
  } else if cname == "audio" {
    add_shape(eid + ".audio", "component", "", 5)
    set_dim(eid + ".audio", "ref", "")
    set_dim(eid + ".audio", "playing", "false")
  } else {
    add_shape(eid + "." + cname, "component", "", 5)
  }
}

print("Created entity: " + eid + " with " + to_string(len(comps)) + " components")
"""
}

world/lore.sl.content:
// Lore: the worldbuilding content system.
//
// Lore IS shapes. Races, classes, magic, history, geography, politics.
// Every piece of lore is a shape with connections to every other piece.
// The lore graph IS the world's memory. Query any node, traverse to any other.
// Consistency IS Law 3: contradictions in lore trigger resolution.
// History IS the trace: every change to the world is a moment.

shape world.lore : world {
  type: system
  layer: 5
  "The living lore of the world. Everything connects to everything."
}

world/editor.sl.content:
// Editor: the worldbuilding tools.
//
// The editor IS part of the world. There is no distinction between
// the tool and the content. Editing a world IS editing shapes.
// The editor shapes ARE shapes in the world.
// You can edit the editor from within the editor.
//
// This is the worldbuilding OS. Not an application that runs on the OS.
// The OS IS the worldbuilding tool IS the world.

shape world.editor : world {
  type: system
  layer: 5
  deps: [world.scene, world.entity, world.terrain, world.physics, hardware.gpu, hardware.audio, hardware.input]
  "The worldbuilding editor. Tools are shapes. Worlds are shapes. Everything is interactive."
}

shape world.editor.select : world.editor {
  type: exec
  layer: 5
  """
// Select an entity or shape in the world.
// Click on it (via raycast from mouse to scene) or name it directly.
// Selected shape becomes the focus of all editing tools.
set_dim("world.editor.state", "selected", target)
print("Selected: " + target)
"""
}

shape world.editor.move : world.editor {
  type: exec
  layer: 5
  """
// Move the selected entity to a new position.
let sel = dim("world.editor.state", "selected")
if sel != "" {
  let tid = sel + ".transform"
  if exists(tid) {
    set_dim(tid, "position", to_string(x) + "," + to_string(y) + "," + to_string(z))
    print("Moved " + sel + " to " + to_string(x) + "," + to_string(y) + "," + to_string(z))
  }
}
"""
}

shape world.editor.spawn : world.editor {
  type: exec
  layer: 5
  """
// Spawn a new entity in the world.
// type: "cube", "sphere", "light", "camera", "empty"
// name: entity name

if type == "cube" {
  // Create entity with transform + mesh + physics.
  let eid = "world.entity." + name
  add_shape(eid, "entity", "", 5)
  add_shape(eid + ".transform", "component", "", 5)
  set_dim(eid + ".transform", "position", default(at, "0,0,0"))
  set_dim(eid + ".transform", "scale", "1,1,1")
  add_shape(eid + ".mesh", "component", "", 5)
  set_dim(eid + ".mesh", "type", "cube")
  set_dim(eid + ".mesh", "color", default(color, "128,128,255"))
  print("Spawned cube: " + name)
} else if type == "light" {
  let eid = "world.entity." + name
  add_shape(eid, "entity", "", 5)
  add_shape(eid + ".transform", "component", "", 5)
  set_dim(eid + ".transform", "position", default(at, "0,10,0"))
  add_shape(eid + ".light", "component", "", 5)
  set_dim(eid + ".light", "type", "point")
  set_dim(eid + ".light", "color", default(color, "255,255,255"))
  set_dim(eid + ".light", "intensity", "100")
  print("Spawned light: " + name)
} else if type == "camera" {
  let eid = "world.entity." + name
  add_shape(eid, "entity", "", 5)
  add_shape(eid + ".transform", "component", "", 5)
  set_dim(eid + ".transform", "position", default(at, "0,5,-10"))
  add_shape(eid + ".camera", "component", "", 5)
  set_dim(eid + ".camera", "fov", "60")
  print("Spawned camera: " + name)
} else {
  let eid = "world.entity." + name
  add_shape(eid, "entity", "", 5)
  add_shape(eid + ".transform", "component", "", 5)
  set_dim(eid + ".transform", "position", default(at, "0,0,0"))
  print("Spawned empty: " + name)
}
"""
}

shape world.editor.inspect : world.editor {
  type: exec
  layer: 5
  """
// Inspect an entity: show all components and their values.
let eid = default(target, dim("world.editor.state", "selected"))
if eid == "" {
  print("Nothing selected")
} else {
  if !exists(eid) {
    print("Entity not found: " + eid)
  } else {
    print("Entity: " + eid)
    let comps = children(eid)
    for comp in comps {
      let cid = eid + "." + comp
      print("  " + comp + ":")
      let d = dims(cid)
      if d != "" {
        let lines = split(d, "\n")
        for line in lines {
          print("    " + line)
        }
      }
      let c = content(cid)
      if c != "" {
        print("    content: " + c)
      }
    }
  }
}
"""
}

world/lore/cosmology.sl.content:
// Cosmology: the creation myth and structure of reality.
//
// Every fantasy world starts here. The cosmology IS the axiom of the world.
// What persists in this universe? What are the laws? What came first?
// The shape theory parallel: the cosmology IS Law 0 for the fictional world.

shape world.lore.cosmology : world.lore {
  type: lore
  layer: 5
  """
// The world's creation and cosmic structure.
//
// Planes of existence (emergence layers of the fictional world):
//   Primordial - raw creation energy, formless
//   Celestial  - realm of gods and cosmic forces
//   Ethereal   - spirit world, dreams, magic substrate
//   Material   - the physical world, mortal realm
//   Shadow     - echo of the material, decay and entropy
//   Abyssal    - void, dissolution, what doesn't cohere
//
// Each plane IS an emergence level. Higher planes see structure
// that lower planes cannot. Gods see the celestial. Mortals see
// the material. Mages reach into the ethereal.
//
// The creation myth: from the Primordial, persistence emerged.
// What cohered became the planes. What didn't cohere became the Abyss.
// The gods ARE the first persistent structures. They don't rule the world.
// They ARE the world's coherence. Law 0 in mythic form.
"""
}

