  """
// GET /office/sheet/{id}/export/xlsx → base64 XLSX (ZIP of XML)
// scope: id = sheet prefix
use "lib.xml"
use "lib.zip"
use "lib.base64"
let prefix = id + "."
let shapes = shapes_under(id)

// Build shared strings and sheet XML.
let strings_xml = ""
let str_count = 0
let rows_xml = ""
let current_row = 0
let row_xml = ""

let i = 0
let n = len(shapes)
while i < n {
  let sid = at(shapes, i)
