let entries = [["[Content_Types].xml", content_types], ["_rels/.rels", rels], ["xl/_rels/workbook.xml.rels", wb_rels], ["xl/workbook.xml", workbook], ["xl/worksheets/sheet1.xml", sheet_xml]]

