os/office/handler/sheet/export/csv.sl.content:
shape os.office.handler.sheet.export.csv : os.office.sheet {
  type: handler
  layer: 4
  """
// GET /office/sheet/{id}/export/csv → CSV text
// scope: id = sheet prefix
let prefix = id + "."
let shapes = shapes_under(id)

// Find max row and col.
let max_row = 0
let max_col = 0
let i = 0
let n = len(shapes)
while i < n {
  let sid = at(shapes, i)
  let i = i + 1
  if !starts_with(sid, prefix) { continue }
  if dim(sid, "type") != "cell" { continue }
  let ref = substring(sid, len(prefix))
  let col = ord(at(ref, 0)) - 64
  let row = to_int(substring(ref, 1))
  if row > max_row { let max_row = row }
  if col > max_col { let max_col = col }
}

// Build CSV row by row.
let row = 1
while row <= max_row {
  let line = ""
  let col = 1
  while col <= max_col {
    let ref = chr(col + 64) + to_string(row)
    let cell_id = id + "." + ref
    let val = content(cell_id)
    if contains(val, ",") {
      let val = "\"" + replace(val, "\"", "\"\"") + "\""
    }
    if col > 1 {
      let line = line + ","
    }
    let line = line + val
    let col = col + 1
  }
  print(line)
  let row = row + 1
}
"""
}

os/office/handler/import/xlsx.sl.content:
shape os.office.handler.import.xlsx : os.office {
  type: handler
  layer: 4
  """
// POST /office/import (xlsx) → import shapes from base64 XLSX
// scope: prefix, file_data (base64)
use "lib.zip"
use "lib.base64"
use "lib.json"
let entries = zip_extract(base64_decode(file_data))

// Find sheet1.xml.
let sheet_content = ""
let i = 0
while i < len(entries) {
  let entry = at(entries, i)
  let i = i + 1
  let name = at(entry, 0)
  if contains(name, "sheet1.xml") {
    let sheet_content = at(entry, 1)
  }
}

if sheet_content == "" {
  print("{\"error\":\"no sheet1.xml found\"}")
}

if sheet_content != "" {
  // Create sheet root.
  add_shape(prefix, "sheet", "")
  set_dim(prefix, "title", "Imported")

  // Parse cells from XML (simple: find <c r="XX"> and <v> or <t> elements).
  let parts = split(sheet_content, "<c ")
  let j = 1
  while j < len(parts) {
    let part = at(parts, j)
    let j = j + 1
    // Extract ref: r="XX"
    let ref_start = index_of(part, "r=\"")
    if ref_start >= 0 {
      let ref_rest = substring(part, ref_start + 3)
      let ref_end = index_of(ref_rest, "\"")
      let ref = substring(ref_rest, 0, ref_end)

      // Extract value from <v>...</v> or <t>...</t>.
      let val = ""
      let v_start = index_of(part, "<v>")
      if v_start >= 0 {
        let v_rest = substring(part, v_start + 3)
        let v_end = index_of(v_rest, "</v>")
        let val = substring(v_rest, 0, v_end)
      }
      let t_start = index_of(part, "<t>")
      if t_start >= 0 {
        let t_rest = substring(part, t_start + 3)
        let t_end = index_of(t_rest, "</t>")
        let val = substring(t_rest, 0, t_end)
      }

      if ref != "" {
        let cell_id = prefix + "." + ref
        add_shape(cell_id, "cell", val)
        set_dim(cell_id, "col", substring(ref, 0, 1))
        set_dim(cell_id, "row", substring(ref, 1))
        set_dim(cell_id, "format", "general")
        add_dep(cell_id, prefix)
      }
    }
  }

  print("{\"status\":\"ok\",\"prefix\":\"" + json_escape(prefix) + "\"}")
}
"""
}

os/office/integration/sheet-embed.sl.content:
shape os.office.integration.sheet-embed : os.office.integration {
  type: func
  layer: 4
  """
// Embed a sheet in a document block.
// Usage: create a block with block_type=sheet, dims[sheet_ref]=<sheet-id>
// The block shape should dep on the sheet root.
// The doc editor JS detects block_type=sheet and renders an inline grid.
fn embed_sheet(doc_id, block_order, sheet_id) {
  let bid = doc_id + ".b." + block_order
  add_shape(bid, "block", 4)
  set_dim(bid, "block_type", "sheet")
  set_dim(bid, "order", block_order)
  set_dim(bid, "sheet_ref", sheet_id)
  add_dep(bid, sheet_id)
  auto "embedded " + sheet_id + " in " + doc_id
}
"""
}

os/office/integration/pivot.sl.content:
shape os.office.integration.pivot : os.office.integration {
  type: func
  layer: 4
  """
// Pivot table: an agent shape that reads source cells, groups, and aggregates.
// The pivot table depends on its source sheet and recomputes via agent.exec.
//
// To create a pivot:
//   shape user.sheet.pivot.sales : user.sheet.data {
//     type: pivot
//     fn: agent.exec
//     source: user.sheet.data
//     rows: category
//     cols: month
//     values: amount
//     agg: sum
//     content: <shape-lang that reads source, groups, aggregates>
//   }
fn create_pivot(name, source, rows_dim, cols_dim, values_dim, agg) {
  let id = "user.sheet.pivot." + name
  add_shape(id, "pivot", 4)
  set_dim(id, "source", source)
  set_dim(id, "rows", rows_dim)
  set_dim(id, "cols", cols_dim)
  set_dim(id, "values", values_dim)
  set_dim(id, "agg", agg)
  add_dep(id, source)
  auto "created pivot " + id
}
"""
}

