os/shell/cmd/wave.sl.content:
shape os.shell.cmd.wave {
  type: exec
  layer: 4
  """
fn wave_walk(id, depth, visited) {
  let dt = dependents(id)
  for dep in dt {
    if !(dep in visited) {
      let indent = repeat("  ", depth)
      let fn_name = dim(dep, "fn")
      let label = if_val(fn_name != "", " [" + fn_name + "]", "")
      print(indent + "-> " + dep + label)
      set visited = append(visited, dep)
      wave_walk(dep, depth + 1, visited)
    }
  }
  absorb
}

if arg0 == "" {
  print("wave: missing shape-id")
} else {
  let id = resolve(prefix, arg0)
  print("Wave from " + id + ":")
  let visited = [id]
  wave_walk(id, 1, visited)
}
"""
}

os/shell/cmd/benchmark.sl.content:
shape os.shell.cmd.benchmark {
  type: exec
  layer: 4
  """
let mc = moments()
if mc == 0 {
  print("No trace moments recorded yet.")
} else {
  print("Benchmark Report")
  print("================")
  print("")

  // Count by action type
  let adds = moments("add")
  let edits = moments("edit")
  let removes = moments("remove")
  let blocks = moments("block")

  print("Total moments:  " + mc)
  print("  adds:         " + adds)
  print("  edits:        " + edits)
  print("  removes:      " + removes)
  print("  blocks:       " + blocks)
  print("")

  // Analyze wave propagation for edits
  if edits > 0 {
    print("Wave Propagation:")
    let total_auto = 0
    let total_flagged = 0
    let max_wave = 0

    for i in range(mc) {
      if moment_action(i) == "edit" {
        let wave = moment_wave(i)
        let auto = len(map_get(wave, "auto_updated"))
        let flagged = len(map_get(wave, "newer_available"))
        let wave_size = auto + flagged
        set total_auto = total_auto + auto
        set total_flagged = total_flagged + flagged
        if wave_size > max_wave {
          set max_wave = wave_size
        }
      }
    }

    print("  total auto-updated: " + total_auto)
    print("  total flagged:      " + total_flagged)
    print("  max wave width:     " + max_wave)
    if edits > 0 {
      print("  avg wave width:     " + round((total_auto + total_flagged) / edits, 1))
    }
    print("")
  }

  // Shape statistics
  print("Shape Graph:")
  print("  total shapes:   " + shape_count())
  print("  global tick:    " + global_tick())
  if mc > 0 {
    print("  ticks/moment:   " + round(global_tick() / mc, 2))
  }
}
"""
}

os/shell/cmd/audit.sl.content:
shape os.shell.cmd.audit {
  type: exec
  layer: 4
  """
// Show detailed audit trail for a user or the current actor.
let target = default(arg0, actor())
if target == "" {
  print("audit: need user ID or login first")
} else {
  print("Audit Trail: " + target)
  print(repeat("=", 50))
  let layers = range(0, 6)
  for l in layers {
    let mc = moments(l)
    let found = false
    for i in range(0, mc) {
      let a = moment_actor(l, i)
      if a == target {
        if !found {
          print("")
          print("Layer " + l)
          set found = true
        }
        let action = moment_action(l, i)
        let tgt = moment_target(l, i)
        let ts = moment_ts(l, i)
        print("  M" + pad_right(i, 4) + " " + pad_right(action, 12) + " " + pad_right(tgt, 30) + " " + ts)
      }
    }
  }
}
"""
}

