os/render/settings/script.sl.content:
shape os.render.settings.script {
  type: script
  layer: 4
  """
(function() {
  var root = document.getElementById('settings');
  var themes = {};
  var currentConfig = {};

  fetch('/shapes').then(function(r) { return r.json(); }).then(function(shapes) {
    shapes.forEach(function(s) {
      if (s.id.indexOf('os.theme.') === 0 && s.character && s.character.dimensions && s.character.dimensions.type === 'theme') {
        var name = s.id.replace('os.theme.', '');
        var bg = '#333', fg = '#ccc', accent = '#77f';
        var c = s.character ? s.character.content : '';
        if (c) {
          var m;
          m = c.match(/--bg:\s*([^;]+)/);
          if (m) bg = m[1].trim();
          m = c.match(/--fg:\s*([^;]+)/);
          if (m) fg = m[1].trim();
          m = c.match(/--accent:\s*([^;]+)/);
          if (m) accent = m[1].trim();
        }
        themes[name] = { id: s.id, bg: bg, fg: fg, accent: accent };
      }
      if (s.id.indexOf('os.config.') === 0) {
        currentConfig[s.id] = s.character ? (s.character.content || '') : '';
      }
    });
    render();
  });

  function saveConfig(id, value) {
    return fetch('/shape', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({
        id: id,
        character: {
          dimensions: {type: 'config'},
          content: value
        }
      })
    });
  }

  function flashStatus(el) {
    el.classList.add('show');
    setTimeout(function() { el.classList.remove('show'); }, 1500);
  }

  function render() {
    var activeTheme = currentConfig['os.config.desktop.theme'] || '';
    var activeWM = currentConfig['os.config.desktop.wm'] || '';
    var background = currentConfig['os.config.desktop.background'] || '';
    var headers = currentConfig['os.config.headers'] || 'on';
    var shellHome = currentConfig['os.config.shell.home'] || 'user';

    var html = '<h1>Settings</h1>';

    html += '<h2>Theme</h2>';
    html += '<div class="theme-grid">';
    var themeNames = Object.keys(themes).sort();
    themeNames.forEach(function(name) {
      var t = themes[name];
      var isActive = activeTheme === t.id ? ' active' : '';
      html += '<div class="theme-card' + isActive + '" data-theme="' + t.id + '">';
      html += '<div class="theme-preview" style="background: linear-gradient(135deg, ' + t.bg + ' 0%, ' + t.accent + ' 100%)"></div>';
      html += name;
      html += '</div>';
    });
    html += '</div>';

    html += '<h2>Window Manager</h2>';
    html += '<div class="setting-row">';
    html += '<div><div class="setting-label">Window Manager</div><div class="setting-desc">How windows are arranged</div></div>';
    html += '<div class="setting-value"><select id="wm-select">';
    html += '<option value="os.wm.floating"' + (activeWM === 'os.wm.floating' ? ' selected' : '') + '>Floating</option>';
    html += '<option value="os.wm.tiling"' + (activeWM === 'os.wm.tiling' ? ' selected' : '') + '>Tiling</option>';
    html += '</select><span class="status" id="wm-status">saved</span></div>';
    html += '</div>';

    html += '<h2>Desktop</h2>';
    html += '<div class="setting-row">';
    html += '<div><div class="setting-label">Background</div><div class="setting-desc">CSS value (color, gradient, or url())</div></div>';
    html += '<div class="setting-value"><input type="text" id="bg-input" value="' + background.replace(/"/g, '&quot;') + '" style="min-width:240px">';
    html += '<span class="status" id="bg-status">saved</span></div>';
    html += '</div>';

    html += '<h2>Shell</h2>';
    html += '<div class="setting-row">';
    html += '<div><div class="setting-label">Home directory</div><div class="setting-desc">Default prefix on login</div></div>';
    html += '<div class="setting-value"><input type="text" id="home-input" value="' + shellHome + '">';
    html += '<span class="status" id="home-status">saved</span></div>';
    html += '</div>';

    html += '<div class="setting-row">';
    html += '<div><div class="setting-label">Column headers</div><div class="setting-desc">Show headers in command output tables</div></div>';
    html += '<div class="setting-value"><select id="headers-select">';
    html += '<option value="on"' + (headers === 'on' ? ' selected' : '') + '>On</option>';
    html += '<option value="off"' + (headers === 'off' ? ' selected' : '') + '>Off</option>';
    html += '</select><span class="status" id="headers-status">saved</span></div>';
    html += '</div>';

    // LLM Agent section.
    var llmKey = currentConfig['os.config.llm.api_key'] || '';
    var llmModel = currentConfig['os.config.llm.model'] || 'claude-sonnet-4-20250514';
    var llmProvider = currentConfig['os.config.llm.provider'] || 'anthropic';
    var llmMaxTokens = currentConfig['os.config.llm.max_tokens'] || '4096';

    html += '<h2>LLM Agent</h2>';
    html += '<div class="setting-row">';
    html += '<div><div class="setting-label">API Key</div><div class="setting-desc">Anthropic API key (or set ANTHROPIC_API_KEY env var)</div></div>';
    html += '<div class="setting-value"><input type="password" id="llm-key-input" value="' + llmKey.replace(/"/g, '&quot;') + '" placeholder="sk-ant-..." style="min-width:240px">';
    html += '<span class="status" id="llm-key-status">saved</span></div>';
    html += '</div>';

    html += '<div class="setting-row">';
    html += '<div><div class="setting-label">Model</div><div class="setting-desc">LLM model identifier</div></div>';
    html += '<div class="setting-value"><input type="text" id="llm-model-input" value="' + llmModel + '" style="min-width:240px">';
    html += '<span class="status" id="llm-model-status">saved</span></div>';
    html += '</div>';

    html += '<div class="setting-row">';
    html += '<div><div class="setting-label">Max tokens</div><div class="setting-desc">Maximum response tokens per step</div></div>';
    html += '<div class="setting-value"><input type="text" id="llm-tokens-input" value="' + llmMaxTokens + '" style="min-width:100px">';
    html += '<span class="status" id="llm-tokens-status">saved</span></div>';
    html += '</div>';

    root.innerHTML = html;

    root.querySelectorAll('.theme-card').forEach(function(card) {
      card.addEventListener('click', function() {
        var themeId = this.dataset.theme;
        saveConfig('os.config.desktop.theme', themeId).then(function() {
          currentConfig['os.config.desktop.theme'] = themeId;
          render();
          if (window.parent !== window) window.parent.location.reload();
        });
      });
    });

    document.getElementById('wm-select').addEventListener('change', function() {
      var val = this.value;
      saveConfig('os.config.desktop.wm', val).then(function() {
        currentConfig['os.config.desktop.wm'] = val;
        flashStatus(document.getElementById('wm-status'));
        if (window.parent !== window) window.parent.location.reload();
      });
    });

    // Debounced save for text inputs — fires on paste/type, not just blur.
    var saveTimers = {};
    function debouncedSave(id, configKey, statusEl, delay) {
      var el = document.getElementById(id);
      if (!el) return;
      el.addEventListener('input', function() {
        var val = el.value;
        if (saveTimers[id]) clearTimeout(saveTimers[id]);
        saveTimers[id] = setTimeout(function() {
          saveConfig(configKey, val).then(function() {
            currentConfig[configKey] = val;
            flashStatus(statusEl);
          });
        }, delay || 500);
      });
    }

    debouncedSave('bg-input', 'os.config.desktop.background', document.getElementById('bg-status'));
    debouncedSave('home-input', 'os.config.shell.home', document.getElementById('home-status'));

    document.getElementById('headers-select').addEventListener('change', function() {
      var val = this.value;
      saveConfig('os.config.headers', val).then(function() {
        currentConfig['os.config.headers'] = val;
        flashStatus(document.getElementById('headers-status'));
      });
    });

    // LLM settings.
    debouncedSave('llm-key-input', 'os.config.llm.api_key', document.getElementById('llm-key-status'));
    debouncedSave('llm-model-input', 'os.config.llm.model', document.getElementById('llm-model-status'));
    debouncedSave('llm-tokens-input', 'os.config.llm.max_tokens', document.getElementById('llm-tokens-status'));
  }
})();
"""
}

os/render/chat/style.sl.content:
shape os.render.chat.style {
  type: style
  layer: 4
  """
* { margin: 0; padding: 0; box-sizing: border-box; }
body {
  background: var(--bg, #1e1e2e);
  color: var(--text, #cdd6f4);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  height: 100vh;
  overflow: hidden;
}
#chat {
  display: flex; flex-direction: column; height: 100vh;
}
#chat-header {
  display: flex; justify-content: space-between; align-items: center;
  padding: 10px 16px;
  background: var(--surface, #181825);
  border-bottom: 1px solid var(--border, #313244);
  font-size: 13px; font-weight: 600;
}
#chat-status {
  font-size: 11px; color: var(--subtext, #a6adc8);
  padding: 2px 8px; border-radius: 10px;
  background: var(--surface, #181825);
  border: 1px solid var(--border, #313244);
}
#chat-status.active { color: var(--green, #a6e3a1); border-color: var(--green, #a6e3a1); }
#chat-status.error { color: var(--red, #f38ba8); border-color: var(--red, #f38ba8); }
#chat-messages {
  flex: 1; overflow-y: auto; padding: 16px;
  display: flex; flex-direction: column; gap: 12px;
}
.msg {
  max-width: 85%; padding: 10px 14px; border-radius: 12px;
  font-size: 13px; line-height: 1.5; white-space: pre-wrap;
  word-break: break-word;
}
.msg.user {
  align-self: flex-end;
  background: var(--accent, #89b4fa); color: #11111b;
  border-bottom-right-radius: 4px;
}
.msg.agent {
  align-self: flex-start;
  background: var(--surface, #313244); color: var(--text, #cdd6f4);
  border-bottom-left-radius: 4px;
}
.msg.error {
  align-self: flex-start;
  background: rgba(243, 139, 168, 0.15); color: var(--red, #f38ba8);
  border: 1px solid rgba(243, 139, 168, 0.3);
  border-bottom-left-radius: 4px;
}
.msg.system {
  align-self: center; text-align: center;
  color: var(--subtext, #a6adc8); font-size: 11px;
  padding: 4px 12px;
}
.msg .step-label {
  font-size: 10px; color: var(--subtext, #a6adc8);
  margin-bottom: 4px; text-transform: uppercase; letter-spacing: 0.5px;
}
.msg code {
  font-family: 'SF Mono', 'Fira Code', monospace; font-size: 12px;
  background: rgba(0,0,0,0.2); padding: 1px 4px; border-radius: 3px;
}
.msg pre {
  font-family: 'SF Mono', 'Fira Code', monospace; font-size: 12px;
  background: rgba(0,0,0,0.3); padding: 8px 10px; border-radius: 6px;
  margin: 6px 0; overflow-x: auto; white-space: pre;
}
.typing {
  align-self: flex-start; color: var(--subtext, #a6adc8);
  font-size: 12px; padding: 8px 14px;
}
.typing::after {
  content: ''; display: inline-block; width: 12px;
  animation: dots 1.4s infinite;
}
@keyframes dots {
  0%, 20% { content: '.'; }
  40% { content: '..'; }
  60%, 100% { content: '...'; }
}
#chat-input-area {
  display: flex; gap: 8px; padding: 12px 16px;
  background: var(--surface, #181825);
  border-top: 1px solid var(--border, #313244);
}
#chat-input {
  flex: 1; resize: none; border: 1px solid var(--border, #313244);
  border-radius: 8px; padding: 10px 14px;
  background: var(--bg, #1e1e2e); color: var(--text, #cdd6f4);
  font-family: inherit; font-size: 13px; line-height: 1.4;
  outline: none; max-height: 120px;
}
#chat-input:focus { border-color: var(--accent, #89b4fa); }
#chat-input::placeholder { color: var(--subtext, #585b70); }
#chat-send {
  width: 40px; height: 40px; border-radius: 8px; border: none;
  background: var(--accent, #89b4fa); color: #11111b;
  font-size: 16px; cursor: pointer; display: flex;
  align-items: center; justify-content: center;
  transition: opacity 0.15s;
}
#chat-send:hover { opacity: 0.85; }
#chat-send:disabled { opacity: 0.4; cursor: not-allowed; }
"""
}

os/render/chat/script.sl.content:
shape os.render.chat.script {
  type: script
  layer: 4
  """
(function() {
  var messages = document.getElementById('chat-messages');
  var input = document.getElementById('chat-input');
  var sendBtn = document.getElementById('chat-send');
  var statusEl = document.getElementById('chat-status');
  var ws = null;
  var sending = false;

  function connect() {
    var proto = location.protocol === 'https:' ? 'wss:' : 'ws:';
    ws = new WebSocket(proto + '//' + location.host + '/ws/chat');

    ws.onopen = function() {
      setStatus('ready', '');
    };

    ws.onmessage = function(e) {
      try {
        var msg = JSON.parse(e.data);
        handleMsg(msg);
      } catch(ex) {
        // Raw text.
        addMessage('agent', e.data);
      }
    };

    ws.onclose = function() {
      setStatus('disconnected', 'error');
      sending = false;
      updateSendBtn();
      setTimeout(connect, 2000);
    };

    ws.onerror = function() { ws.close(); };
  }

  function handleMsg(msg) {
    switch (msg.type) {
      case 'status':
        setStatus(msg.content, 'active');
        if (msg.content === 'connected') {
          // Don't show as message.
        } else {
          removeTyping();
          addTyping();
        }
        break;

      case 'step':
        removeTyping();
        if (msg.content && msg.content.trim()) {
          addStepMessage(msg.step, msg.content);
        }
        addTyping();
        break;

      case 'complete':
        removeTyping();
        sending = false;
        updateSendBtn();
        setStatus('ready', '');
        addMessage('system', msg.content);
        break;

      case 'error':
        removeTyping();
        sending = false;
        updateSendBtn();
        setStatus('error', 'error');
        addMessage('error', msg.content);
        break;

      case 'history':
        // Restore chat history.
        try {
          var hist = JSON.parse(msg.content);
          hist.forEach(function(h) {
            addMessage(h.role, h.text, true);
          });
        } catch(ex) {}
        break;
    }
  }

  function addMessage(role, text, noScroll) {
    var el = document.createElement('div');
    el.className = 'msg ' + role;
    el.textContent = text;
    messages.appendChild(el);
    if (!noScroll) scrollBottom();
  }

  function addStepMessage(step, text) {
    var el = document.createElement('div');
    el.className = 'msg agent';
    var label = document.createElement('div');
    label.className = 'step-label';
    label.textContent = 'Step ' + step;
    el.appendChild(label);
    // Check if text looks like code.
    if (text.indexOf('add_shape') >= 0 || text.indexOf('set_content') >= 0 || text.indexOf('VERIFY') >= 0) {
      var pre = document.createElement('pre');
      pre.textContent = text;
      el.appendChild(pre);
    } else {
      var span = document.createElement('span');
      span.textContent = text;
      el.appendChild(span);
    }
    messages.appendChild(el);
    scrollBottom();
  }

  function addTyping() {
    var el = document.createElement('div');
    el.className = 'typing';
    el.id = 'typing-indicator';
    el.textContent = 'thinking';
    messages.appendChild(el);
    scrollBottom();
  }

  function removeTyping() {
    var el = document.getElementById('typing-indicator');
    if (el) el.remove();
  }

  function setStatus(text, cls) {
    statusEl.textContent = text;
    statusEl.className = cls || '';
  }

  function scrollBottom() {
    messages.scrollTop = messages.scrollHeight;
  }

  function updateSendBtn() {
    sendBtn.disabled = sending;
    input.disabled = sending;
    if (!sending) input.focus();
  }

  function send() {
    var text = input.value.trim();
    if (!text || sending) return;

    addMessage('user', text);
    sending = true;
    updateSendBtn();

    // Save to chat history.
    saveHistory('user', text);

    ws.send(JSON.stringify({type: 'message', content: text}));
    input.value = '';
    autoResize();
  }

  function saveHistory(role, text) {
    // Append to session shape.
    fetch('/api/shape/os.session.chat.history').then(function(r) {
      return r.json();
    }).then(function(shape) {
      var hist = [];
      try { hist = JSON.parse(shape.character.content || '[]'); } catch(ex) {}
      hist.push({role: role, text: text, ts: Date.now()});
      // Keep last 100 messages.
      if (hist.length > 100) hist = hist.slice(-100);
      return fetch('/shape', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({
          id: 'os.session.chat.history',
          character: {dimensions: {type: 'session'}, content: JSON.stringify(hist)}
        })
      });
    }).catch(function() {});
  }

  // Auto-resize textarea.
  function autoResize() {
    input.style.height = 'auto';
    input.style.height = Math.min(input.scrollHeight, 120) + 'px';
  }

  sendBtn.addEventListener('click', send);
  input.addEventListener('keydown', function(e) {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      send();
    }
  });
  input.addEventListener('input', autoResize);

  connect();
})();
"""
}

os/render/terminal/style.sl.content:
shape os.render.terminal.style {
  type: style
  layer: 4
  """
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body {
  height: 100%;
  background: var(--bg);
  color: var(--fg);
  font-family: 'SF Mono', 'Fira Code', 'JetBrains Mono', 'Cascadia Code', monospace;
  font-size: 13px;
  line-height: 1.5;
}
#terminal {
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 0;
}
#output {
  flex: 1;
  overflow-y: auto;
  padding: 12px 16px;
  white-space: pre-wrap;
  word-wrap: break-word;
}
#output .prompt { color: var(--prompt); }
#output .error { color: var(--error); }
#output .dim { color: var(--dim); }
#output .accent { color: var(--accent); }
#input-line {
  display: flex;
  align-items: center;
  padding: 8px 16px;
  border-top: 1px solid var(--border);
  background: var(--bg);
}
#input-line .prompt {
  color: var(--prompt);
  white-space: pre;
  flex-shrink: 0;
}
#input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  color: var(--fg);
  font-family: inherit;
  font-size: inherit;
  line-height: inherit;
  caret-color: var(--cursor);
}
#input::selection { background: var(--selection); }
#status {
  display: flex;
  justify-content: space-between;
  padding: 4px 16px;
  font-size: 11px;
  color: var(--dim);
  border-top: 1px solid var(--border);
  background: var(--bg-dark, #16161e);
}
.welcome {
  color: var(--dim);
  margin-bottom: 8px;
}
"""
}

os/render/terminal/script.sl.content:
shape os.render.terminal.script {
  type: script
  layer: 4
  """
(function() {
  var output = document.getElementById('output');
  var input = document.getElementById('input');
  var promptEl = document.getElementById('prompt');
  var statusLeft = document.getElementById('status-left');
  var history = [];
  var historyIdx = -1;
  var ws = null;
  var currentPrompt = 'shape$ ';
  var firstMessage = true;

  function connect() {
    var proto = location.protocol === 'https:' ? 'wss:' : 'ws:';
    ws = new WebSocket(proto + '//' + location.host + '/ws/terminal');
    firstMessage = true;

    ws.onopen = function() {
      statusLeft.textContent = 'connected';
    };

    ws.onmessage = function(e) {
      var text = e.data;

      if (text.indexOf('__NAV__') === 0) {
        var url = text.substring(7).trim();
        if (url.indexOf('/') === 0) url = location.origin + url;
        window.open(url, '_blank');
        return;
      }

      if (firstMessage && text.length > 100) {
        firstMessage = false;
        appendOutput(text);
        output.scrollTop = output.scrollHeight;
        return;
      }
      firstMessage = false;

      var lines = text.split('\n');
      var last = lines[lines.length - 1];
      if (last.match(/^shape(:.+)?\$ $/)) {
        currentPrompt = last;
        promptEl.textContent = currentPrompt;
        var rest = lines.slice(0, -1).join('\n');
        if (rest) appendOutput(rest + '\n');
      } else if (text.match(/^shape(:.+)?\$ $/)) {
        currentPrompt = text;
        promptEl.textContent = currentPrompt;
      } else {
        appendOutput(text);
      }
      output.scrollTop = output.scrollHeight;
    };

    ws.onclose = function() {
      statusLeft.textContent = 'disconnected';
      appendOutput('\n[disconnected]\n');
    };

    ws.onerror = function() {
      statusLeft.textContent = 'error';
    };
  }

  function appendOutput(text) {
    if (text.indexOf('error:') >= 0) {
      var span = document.createElement('span');
      span.className = 'error';
      span.textContent = text;
      output.appendChild(span);
    } else {
      output.appendChild(document.createTextNode(text));
    }
  }

  input.addEventListener('keydown', function(e) {
    if (e.key === 'Enter') {
      var cmd = input.value;
      input.value = '';
      historyIdx = -1;

      var cmdLine = document.createElement('div');
      var promptSpan = document.createElement('span');
      promptSpan.className = 'prompt';
      promptSpan.textContent = currentPrompt;
      cmdLine.appendChild(promptSpan);
      cmdLine.appendChild(document.createTextNode(cmd));
      output.appendChild(cmdLine);
      output.scrollTop = output.scrollHeight;

      if (cmd.trim()) {
        history.push(cmd);
        if (ws && ws.readyState === WebSocket.OPEN) {
          ws.send(JSON.stringify({type: 'input', data: cmd + '\n'}));
        }
      } else {
        promptEl.textContent = currentPrompt;
      }

      e.preventDefault();
    } else if (e.key === 'ArrowUp') {
      if (history.length > 0) {
        if (historyIdx < 0) historyIdx = history.length;
        historyIdx--;
        if (historyIdx >= 0) input.value = history[historyIdx];
      }
      e.preventDefault();
    } else if (e.key === 'ArrowDown') {
      if (historyIdx >= 0) {
        historyIdx++;
        if (historyIdx < history.length) {
          input.value = history[historyIdx];
        } else {
          input.value = '';
          historyIdx = -1;
        }
      }
      e.preventDefault();
    } else if (e.key === 'l' && e.ctrlKey) {
      output.innerHTML = '';
      e.preventDefault();
    }
  });

  document.addEventListener('click', function() { input.focus(); });

  fetch('/api/shape/os.session.shell.history')
    .then(function(r) { return r.ok ? r.json() : null; })
    .then(function(sh) {
      if (sh && sh.character && sh.character.content) {
        history = sh.character.content.split('\n').filter(function(l) { return l; });
      }
    })
    .catch(function() {});

  connect();
})();
"""
}

