os/container/run.sl.content:
shape os.container.run : os.container {
  type: exec
  layer: 4
  """
// container run <stack> <program> [flags]
//
// Create and start a container.
//
// Arguments:
//   stack:    comma-separated substrate layers.
//             "mos6502", "riscv64,shape-engine", "arm64,go,shape-engine"
//   program:  path to program or shape ID to execute.
//   flags:
//     --name <name>       Container name (auto-generated if omitted)
//     --rm                Remove container after exit
//     --detach / -d       Run in background
//     --interactive / -i  Keep stdin open
//     --tty / -t          Allocate pseudo-TTY
//     --env KEY=VAL       Set environment variable
//     --mount <src>:<dst> Mount host shape path into container
//     --memory <limit>    Memory limit (e.g. "64KB", "16MB")
//     --cycles <limit>    Cycle budget per tick
//     --caps <list>       Allowed syscalls (e.g. "0,1,2,3,4,5,9")
//     --network <name>    Connect to container network
//     --port <host>:<guest> Forward port
//     --volume <name>:<path> Attach volume
//     --restart <policy>  "no", "always", "on-failure"
//
// Examples:
//   container run mos6502 game.prg -it
//   container run riscv64,shape-engine app.sl -d --name my-app
//   container run arm64,go,shape-engine,shape-os os.img --memory 256MB
//   container run shape-engine hello.sl --rm
//
// What happens:
//   1. Parse stack string into substrate layers.
//   2. Create container shape: os.container.instances.<id>
//   3. Initialize each substrate layer (allocate memory, reset).
//   4. Load program into top layer.
//   5. Configure passthrough (stdio, mounts, caps).
//   6. If --detach: return container ID immediately.
//      Else: attach stdio and run until exit.

let id = default(flag("name"), "c" + global_tick())
let stack = arg0
let program = arg1
let detach = has_flag("detach") || has_flag("d")
let interactive = has_flag("interactive") || has_flag("i")
let rm_after = has_flag("rm")

// Create container shape
let cid = "os.container.instances." + id
add_shape(cid, "container", "", 4)
set_dim(cid, "stack", stack)
set_dim(cid, "program", program)
set_dim(cid, "status", "created")
set_dim(cid, "cycles", "0")
set_dim(cid, "memory", default(flag("memory"), "64MB"))
set_dim(cid, "restart", default(flag("restart"), "no"))

if detach {
  set_dim(cid, "status", "running")
  print("Container " + id + " started (detached)")
} else {
  set_dim(cid, "status", "running")
  print("Container " + id + " started")
}
  """
}

os/container/build.sl.content:
shape os.container.build : os.container {
  type: exec
  layer: 4
  """
// container build <containerfile> [--name <name>]
//
// Build a container image from a Containerfile.
//
// Containerfile format (shape-lang, not Dockerfile):
//
//   shape my-image {
//     type: containerfile
//     """
//     from shape-engine              // base stack
//
//     env APP_ENV "production"       // set environment
//     env PORT "8080"
//
//     copy app.sl /app/              // copy shapes into image
//     copy lib/ /lib/
//
//     mount db-data /data            // declare volume mount
//
//     expose 8080                    // declare port
//
//     run "shape-lang setup.sl"      // run build command
//
//     entrypoint "app/server.sl"     // default program
//     """
//   }
//
// Unlike Dockerfile:
//   FROM -> from: selects the computation stack, not a base image.
//   COPY -> copy: copies shapes into the container's namespace.
//   RUN -> run: executes shape-lang during build.
//   No layers. No caching. No union filesystem.
//   The "image" is a shape with all its deps.
//   Building = constructing the shape with its deps resolved.
//
// What build does:
//   1. Parse the Containerfile shape.
//   2. Create image shape: os.container.images.<name>
//   3. Set stack from "from" directive.
//   4. Copy referenced shapes into image namespace.
//   5. Set environment dimensions.
//   6. Execute "run" commands in a temporary container.
//   7. Set entrypoint.
//   8. The image is ready. It's a shape.

let file = arg0
let name = default(flag("name"), arg0)

if !exists(file) {
  print("Error: containerfile " + file + " not found")
  flag
}

let img = "os.container.images." + name
add_shape(img, "container-image", content(file), 4)
print("Built image " + name + " from " + file)
  """
}

os/container/compose.sl.content:
shape os.container.compose : os.container, os.container.network, os.container.volume {
  type: exec
  layer: 4
  """
// container compose <command> [flags]
//
// Multi-container orchestration from a compose file.
//
// Commands:
//   container compose up [-d] [--file <path>]
//   container compose down [--volumes]
//   container compose ps
//   container compose logs [service]
//   container compose restart [service]
//   container compose build [service]
//   container compose exec <service> <command>
//   container compose scale <service>=<n>
//
// Compose file format (shape-lang, not YAML):
//
//   shape my-project.compose {
//     type: compose
//     """
//     // Services
//     service "web" {
//       stack: "riscv64,shape-engine"
//       program: "app/web-server.sl"
//       port: "8080:80"
//       env: {DB_HOST: "db", DB_PORT: "5432"}
//       depends_on: ["db", "cache"]
//       restart: "always"
//       memory: "128MB"
//     }
//
//     service "db" {
//       stack: "shape-engine"
//       program: "app/database.sl"
//       volume: "db-data:/data"
//       env: {DB_NAME: "myapp"}
//       restart: "always"
//       memory: "256MB"
//     }
//
//     service "cache" {
//       stack: "shape-engine"
//       program: "app/cache.sl"
//       memory: "64MB"
//     }
//
//     service "worker" {
//       stack: "arm64,go,shape-engine"
//       program: "app/worker.sl"
//       depends_on: ["db", "cache"]
//       scale: 3
//       restart: "on-failure"
//     }
//
//     // Networks
//     network "frontend" { type: "bridge" }
//     network "backend" { type: "isolated" }
//
//     // Volumes
//     volume "db-data" {}
//     """
//   }
//
// What compose up does:
//   1. Parse the compose shape.
//   2. Create networks first.
//   3. Create volumes.
//   4. Start services in dependency order:
//      - Services with no depends_on start first.
//      - Services depending on started services start next.
//      - This IS topological sort on the dep graph.
//      - Which IS what the shape engine already does.
//   5. Connect services to networks.
//   6. Mount volumes.
//   7. Print service status.
//
// Dependency resolution:
//   depends_on is a shape dep. The compose up command walks
//   the dep graph and starts services in order. This is wave
//   propagation: "db" starts, wave propagates to "web" and
//   "worker" which depend on "db". They start. The compose
//   file IS the shape graph. The orchestration IS the engine.
//
// Scaling:
//   container compose scale worker=5
//   Creates 5 instances of the worker service.
//   Each instance is a separate container with the same config.
//   Load balancing: round-robin across instances.
//   The instances are child shapes of the service shape.
//
// Unlike Docker Compose:
//   No YAML. Shape-lang.
//   No build step. Shapes are already loaded.
//   No image pull. Shapes are local.
//   No layer caching. Shapes are structural.
//   Dependency resolution IS wave propagation.
//   Scaling IS adding child shapes.
//   Health checks ARE Law 0 (what persists must cohere).

let cmd = arg0

if cmd == "up" {
  let file = default(flag("file"), "compose")
  let detach = has_flag("d")
  print("Starting services from " + file + "...")

  // Find compose shape
  if !exists(file) {
    print("Error: compose file " + file + " not found")
    flag
  }

  // Parse services (simplified: read children)
  let services = children(file)
  print("Services: " + len(services))
  for svc in services {
    print("  Starting " + svc + "...")
  }
  print("All services started.")
}
else if cmd == "down" {
  print("Stopping all services...")
  let instances = children("os.container.instances")
  for inst in instances {
    let cid = "os.container.instances." + inst
    set_dim(cid, "status", "stopped")
  }
  print("All services stopped.")
  if has_flag("volumes") {
    print("Removing volumes...")
  }
}
else if cmd == "ps" {
  print("NAME          STATUS    STACK                    CYCLES")
  print("-------------------------------------------------------")
  let instances = children("os.container.instances")
  for inst in instances {
    let cid = "os.container.instances." + inst
    let status = dim(cid, "status")
    let stack = dim(cid, "stack")
    let cycles = dim(cid, "cycles")
    print(inst + "    " + status + "    " + stack + "    " + cycles)
  }
}
else if cmd == "logs" {
  let svc = default(arg1, "")
  if svc == "" {
    print("Usage: container compose logs <service>")
  } else {
    let cid = "os.container.instances." + svc
    if exists(cid + ".log") {
      print(content(cid + ".log"))
    } else {
      print("(no output)")
    }
  }
}
  """
}

os/container/benchmark.sl.content:
shape os.container.benchmark : os.container, os.time {
  type: system
  layer: 4
  """
// container benchmark <suite> [flags]
//
// Run well-known industry benchmarks inside containers.
// Each benchmark runs in its own container with a defined stack.
// Results are compared against published reference values.
//
// Suites:
//   container benchmark all           Run everything
//   container benchmark compute       CPU/memory benchmarks
//   container benchmark io            Disk/network benchmarks
//   container benchmark language      Language shootout
//   container benchmark system        Full system benchmarks
//   container benchmark dilation      Time dilation experiment
//
// Every benchmark is timed at the host level (wall clock)
// AND at the container level (ticks). The ratio IS the time
// dilation factor for that container's computation stack.
  """
}

os/container/stop.sl.content:
shape os.container.stop : os.container {
  type: exec
  layer: 4
  """
// container stop <id> [--timeout <seconds>]
//
// Stop a running container. Sends graceful shutdown signal
// to the top layer, waits for exit, then checkpoints state.
//
// If --timeout expires before graceful shutdown, force-kills.

let id = arg0
let cid = "os.container.instances." + id

if !exists(cid) {
  print("Error: container " + id + " not found")
  flag
}

let status = dim(cid, "status")
if status != "running" {
  print("Error: container " + id + " is not running (status: " + status + ")")
  flag
}

set_dim(cid, "status", "stopped")
print("Container " + id + " stopped")
  """
}

os/container/exec.sl.content:
shape os.container.exec : os.container {
  type: exec
  layer: 4
  """
// container exec <id> <command> [args...]
//
// Execute a command inside a running container.
// The command runs at the top layer of the container's stack.
//
// Examples:
//   container exec c01 ls
//   container exec c01 cat law.persistence
//   container exec c01 shape-lang "print(1+1)"

let id = arg0
let cmd = arg1
let cid = "os.container.instances." + id

if !exists(cid) {
  print("Error: container " + id + " not found")
  flag
}

let status = dim(cid, "status")
if status != "running" {
  print("Error: container " + id + " is not running")
  flag
}

// Execute command in container context
print("[" + id + "] $ " + cmd)
// The command is evaluated in the container's shape context.
// Passthrough: output goes to host stdout.
  """
}

os/container/rm.sl.content:
shape os.container.rm : os.container {
  type: exec
  layer: 4
  """
// container rm <id> [--force / -f]
//
// Remove a stopped container. With --force, stop and remove.

let id = arg0
let cid = "os.container.instances." + id

if !exists(cid) {
  print("Error: container " + id + " not found")
  flag
}

let status = dim(cid, "status")
if status == "running" {
  if has_flag("force") || has_flag("f") {
    set_dim(cid, "status", "stopped")
  } else {
    print("Error: container " + id + " is running. Use --force to stop and remove.")
    flag
  }
}

// Remove container shape and all child shapes
let kids = children(cid)
for kid in kids {
  rm(cid + "." + kid)
}
rm(cid)
print("Container " + id + " removed")
  """
}

os/container/cp.sl.content:
shape os.container.cp : os.container {
  type: exec
  layer: 4
  """
// container cp <src> <container>:<dst>
// container cp <container>:<src> <dst>
//
// Copy shapes between host and container.
//
// Unlike docker cp: no tar, no filesystem layer.
// Copying a shape = creating a shape in the target namespace
// with the same content and dimensions.

let src = arg0
let dst = arg1

if contains(src, ":") {
  // Container to host
  let parts = split(src, ":")
  let cid = "os.container.instances." + parts[0]
  let src_path = parts[1]
  print("Copied " + src_path + " from " + parts[0] + " to " + dst)
} else if contains(dst, ":") {
  // Host to container
  let parts = split(dst, ":")
  let cid = "os.container.instances." + parts[0]
  let dst_path = parts[1]
  print("Copied " + src + " to " + parts[0] + ":" + dst_path)
}
  """
}

os/container/commit.sl.content:
shape os.container.commit : os.container {
  type: exec
  layer: 4
  """
// container commit <id> <name>
//
// Save a container's current state as a named shape.
// The committed shape includes: stack config, memory snapshot,
// register state, program, mounts, env. Everything needed
// to resume exactly where the container stopped.
//
// Unlike Docker images: no layers, no diffs, no registry.
// A committed container is a shape. It lives in the graph.
// It can be deps'd, edited, propagated. It IS the image.
//
// Examples:
//   container commit c01 my-app-v1
//   container run shape-engine my-app-v1        # resume from snapshot
//   container commit c02 dev-environment
//   container run riscv64 dev-environment       # different stack, same state

let id = arg0
let name = arg1
let cid = "os.container.instances." + id

if !exists(cid) {
  print("Error: container " + id + " not found")
  flag
}

let dst = "os.container.images." + name
add_shape(dst, "container-image", content(cid), 4)

// Copy all dimensions
set_dim(dst, "stack", dim(cid, "stack"))
set_dim(dst, "program", dim(cid, "program"))
set_dim(dst, "memory", dim(cid, "memory"))
set_dim(dst, "cycles", dim(cid, "cycles"))
set_dim(dst, "committed_from", id)

print("Committed " + id + " as " + name)
  """
}

os/container/attach.sl.content:
shape os.container.attach : os.container {
  type: exec
  layer: 4
  """
// container attach <id>
//
// Attach stdin/stdout/stderr to a running container.
// Ctrl-C to detach (container keeps running).

let id = arg0
let cid = "os.container.instances." + id

if !exists(cid) {
  print("Error: container " + id + " not found")
  flag
}

let status = dim(cid, "status")
if status != "running" {
  print("Error: container " + id + " is not running")
  flag
}

print("Attached to " + id + ". Ctrl-C to detach.")
// Passthrough: host stdin -> container stdin
//              container stdout -> host stdout
  """
}

os/container/logs.sl.content:
shape os.container.logs : os.container {
  type: exec
  layer: 4
  """
// container logs <id> [flags]
//
// Show stdout/stderr output from a container.
//   --follow / -f   Stream output continuously
//   --tail <n>      Show last n lines
//   --timestamps    Show timestamps

let id = arg0
let cid = "os.container.instances." + id

if !exists(cid) {
  print("Error: container " + id + " not found")
  flag
}

let log_id = cid + ".log"
if exists(log_id) {
  let log = content(log_id)
  let lines = split(log, "\n")
  let tail = to_int(default(flag("tail"), "0"))
  if tail > 0 {
    let start = len(lines) - tail
    if start < 0 { set start = 0 }
    for i in range(start, len(lines)) {
      print(lines[i])
    }
  } else {
    print(log)
  }
} else {
  print("(no output)")
}
  """
}

os/container/inspect.sl.content:
shape os.container.inspect : os.container {
  type: exec
  layer: 4
  """
// container inspect <id>
//
// Show detailed container state.

let id = arg0
let cid = "os.container.instances." + id

if !exists(cid) {
  print("Error: container " + id + " not found")
  flag
}

print("Container: " + id)
print("====================")
print("Stack:     " + dim(cid, "stack"))
print("Program:   " + dim(cid, "program"))
print("Status:    " + dim(cid, "status"))
print("Cycles:    " + dim(cid, "cycles"))
print("Memory:    " + dim(cid, "memory"))
print("Restart:   " + dim(cid, "restart"))
print("")
print("Mounts:")
let mounts = children(cid + ".mounts")
for m in mounts {
  print("  " + content(cid + ".mounts." + m))
}
print("")
print("Env:")
let envs = children(cid + ".env")
for e in envs {
  print("  " + e + "=" + content(cid + ".env." + e))
}
  """
}

os/container/volume.sl.content:
shape os.container.volume : os.container {
  type: exec
  layer: 4
  """
// container volume <command> [args]
//
// Manage persistent volumes.
//
// A volume is a shape subtree that persists independently of
// any container. Containers mount volumes to share or persist
// data across restarts.
//
// Commands:
//   container volume create <name>
//   container volume ls
//   container volume rm <name>
//   container volume inspect <name>
//
// Unlike Docker volumes: no drivers, no mount points, no tmpfs.
// A volume IS a shape subtree. Mounting = adding a dep.
// The shape graph handles persistence automatically.
// Volumes persist because shapes persist (Law 0).

let cmd = arg0

if cmd == "create" {
  let name = arg1
  let vid = "os.container.volumes." + name
  add_shape(vid, "container-volume", "", 4)
  print("Volume " + name + " created")
}
else if cmd == "ls" {
  let vols = children("os.container.volumes")
  print("NAME          SIZE")
  print("-------------------")
  for v in vols {
    let vid = "os.container.volumes." + v
    let kids = children(vid)
    print(v + "    " + len(kids) + " shapes")
  }
}
else if cmd == "rm" {
  let name = arg1
  let vid = "os.container.volumes." + name
  rm(vid)
  print("Volume " + name + " removed")
}
  """
}

os/container/network.sl.content:
shape os.container.network : os.container {
  type: exec
  layer: 4
  """
// container network <command> [args]
//
// Manage container networks.
//
// Networks are shapes that connect containers. A container
// connected to a network can communicate with other containers
// on the same network through shape references.
//
// Commands:
//   container network create <name>
//   container network ls
//   container network rm <name>
//   container network connect <network> <container>
//   container network disconnect <network> <container>
//   container network inspect <name>
//
// Unlike Docker networks: no bridges, no iptables, no DNS.
// A network IS a shape. Containers connected to it are deps.
// Communication is wave propagation through the network shape.
// "Sending a message" = editing a shape on the network.
// "Receiving a message" = being a dependent of that shape.
//
// Network types:
//   bridge (default): containers can reach each other and host.
//   isolated: containers can reach each other only.
//   host: container shares host shape namespace (no isolation).

let cmd = arg0

if cmd == "create" {
  let name = arg1
  let nid = "os.container.networks." + name
  add_shape(nid, "container-network", "", 4)
  set_dim(nid, "type", default(flag("driver"), "bridge"))
  print("Network " + name + " created")
}
else if cmd == "ls" {
  let nets = children("os.container.networks")
  print("NAME          TYPE        CONTAINERS")
  print("-------------------------------------")
  for n in nets {
    let nid = "os.container.networks." + n
    let typ = dim(nid, "type")
    let conns = children(nid + ".members")
    print(n + "    " + typ + "    " + len(conns))
  }
}
else if cmd == "connect" {
  let net = arg1
  let ctr = arg2
  let mid = "os.container.networks." + net + ".members." + ctr
  add_shape(mid, "network-member", "", 4)
  print("Connected " + ctr + " to " + net)
}
else if cmd == "disconnect" {
  let net = arg1
  let ctr = arg2
  rm("os.container.networks." + net + ".members." + ctr)
  print("Disconnected " + ctr + " from " + net)
}
  """
}

os/container/ps.sl.content:
shape os.container.ps : os.container {
  type: exec
  layer: 4
  """
// container ps [flags]
//
// List containers.
//   --all / -a    Show all containers (including stopped)
//
// Output:
//   ID      STACK                    STATUS    CYCLES     MEMORY
//   c01     mos6502                  running   1.2M       64KB
//   c02     riscv64/shape-engine     running   450K       16MB
//   c03     arm64/go/shape-engine    stopped   89K        256MB

let show_all = has_flag("all") || has_flag("a")
let prefix = "os.container.instances"
let kids = children(prefix)

print("ID        STACK                        STATUS    CYCLES      MEMORY")
print("----------------------------------------------------------------------")

for kid in kids {
  let cid = prefix + "." + kid
  let status = dim(cid, "status")
  if status == "running" || show_all {
    let stack = dim(cid, "stack")
    let cycles = dim(cid, "cycles")
    let mem = dim(cid, "memory")
    print(kid + "    " + stack + "    " + status + "    " + cycles + "    " + mem)
  }
}
  """
}

os/container/benchmark/cpu.sl.content:
shape os.container.benchmark.cpu : os.container.benchmark {
  type: exec
  layer: 4
  """
// Shape CPU (3.7 MHz RISC processor) benchmark.
//
// The shape CPU runs inside the shape engine. Every instruction
// is a shape graph traversal: fetch instruction shape, decode
// dimensions, read register shapes, compute, write result shape.
//
// | Operation                    | Latency   | Throughput     |
// |------------------------------|-----------|----------------|
// | Register read                | 14 ns     | 70M/sec        |
// | Register write               | 247 ns    | 4.0M/sec       |
// | Memory read (1KB)            | 77 ns     | 12.9M/sec      |
// | Memory write (1KB)           | 135 ns    | 7.4M/sec       |
// | ALU add (full cycle)         | 174 ns    | 5.8M/sec       |
// | ALU multiply (full cycle)    | 169 ns    | 5.9M/sec       |
// | Single instruction           | 508 ns    | 2.0 MIPS       |
// | 5-instruction program        | 1.52 us   | 3.3 MIPS       |
// | 100-iteration loop           | 39.3 us   | 2.5 MIPS       |
// | 1000 instructions sustained  | 272 us    | 3.7 MIPS       |
// | Register + 4 forwarding deps | 440 ns    | 2.3M/sec       |
//
// Effective clock: 3.7 MHz.
// All arithmetic: arbitrary precision. Zero precision loss.
//
// The 3.7 MHz shape processor solves the full canopy in
// polynomial time because it reads structure, not iterates.
//
// | Problem      | Turing (5 GHz) | Shape (3.7 MHz) | Ratio      |
// |--------------|----------------|-----------------|------------|
// | 3-SAT n=20   | 200 us         | 2.2 us          | 91x        |
// | 3-SAT n=50   | 2.3 days       | 34 us           | 5.9 x 10^9|
// | 3-SAT n=100  | heat death     | 270 us          | infinite   |
// | 3-SAT n=1000 | ---            | 270 ms          | ---        |

print("=== Shape CPU Benchmark (3.7 MHz) ===")
print("")
print("OPERATION                     LATENCY     THROUGHPUT")
print("-----------------------------------------------------")
print("Register read                 14 ns       70M/sec")
print("Register write                247 ns      4.0M/sec")
print("Memory read                   77 ns       12.9M/sec")
print("Memory write                  135 ns      7.4M/sec")
print("ALU add                       174 ns      5.8M/sec")
print("ALU multiply                  169 ns      5.9M/sec")
print("Single instruction            508 ns      2.0 MIPS")
print("1000 instr sustained          272 us      3.7 MIPS")
print("")
print("Effective clock: 3.7 MHz")
print("Precision: exact rational (zero loss)")
  """
